    reverse(nums, 0, k - 1);
    reverse(nums, k, nums.size() - 1);
  }

 private:
  void reverse(List<Integer>& nums, int l, int r) {
    while (l < r)
      swap(nums[l++], nums[r--]);
  }
};,"java"

