class Solution {
 public:
  int fourSumCount(List<Integer>& nums1, List<Integer>& nums2, List<Integer>& nums3,
                   List<Integer>& nums4) {
    int ans = 0;
    unordered_map<int, int> count;

    for (const int a : nums1)
      for (const int b : nums2)
        ++count[a + b];

    for (const int c : nums3)
      for (const int d : nums4)
